1	/* ============================ Tự khám phá: điều phối chế độ bay dù lượn ============================
2	   Nối flight (mô hình), glider (dù), chase (camera) với vòng animate, phím và URL.
3	   `?explore=glider` bay thẳng; không tham số (hoặc `?test&chooser`) hiện màn chọn; Esc tải lại trang không còn tham số explore. Camera do explore.update đặt sau updateCamera. */
4	import * as THREE from 'three';
5	import { scene, camera, controls } from '../core/renderer';
6	import { cam, keys } from '../views/state';
7	import { exCreate, exStep, exInputFromKeys, type GliderState, type GliderInput } from './flight';
8	import { exBuildGlider, exPlaceGlider } from './glider';
9	import { exChase } from './chase';
10	import { exShowChooser } from './chooser';
11	import { exNight, exNightBind, exNightStep } from './nightShows';
12	import type { SwingController } from '../bridges/song-han/SwingController';
13	
14	const _inp: GliderInput = { turn: 0, climb: 0, throttle: 0 };   // đầu vào tái dùng mỗi khung
15	
16	let glider: THREE.Group | null = null;
17	let state: GliderState | null = null;
18	let readout = '';   // chữ đang hiện ở #exSpeed: chỉ ghi DOM khi đổi
19	
20	const active = () => cam.mode === 'glider' && state !== null;
21	
22	/* Đồng hồ tốc độ (km/h) và độ cao (m): chỉ số và đơn vị nên không cần dịch */
23	function exShowSpeed(): void {
24	  const t = `${Math.round(state!.speed * 3.6)} km/h · ${Math.round(state!.pos.y)} m`;
25	  if (t === readout) return;
26	  readout = t;
27	  const el = document.getElementById('exSpeed'); if (el) el.textContent = t;
28	}
29	
30	/* Một bước: mô phỏng, đặt dù, đặt camera bám */
31	function advance(dt: number, inp: GliderInput): void {
32	  exStep(state!, inp, dt);
33	  exPlaceGlider(glider!, state!);
34	  exChase(camera, controls.target, state!, dt);
35	  exShowSpeed();
36	  exNightStep(dt);
37	}
38	
39	export const explore = {
40	  active,
41	  nightShows: exNight,
42	  get state() { return state; },
43	  get glider() { return glider; },
44	  start(): void {
45	    state = exCreate();
46	    if (!glider) glider = exBuildGlider();
47	    if (!glider.parent) scene.add(glider);
48	    cam.flight.then = null; cam.mode = 'glider'; controls.enabled = false;
49	    exPlaceGlider(glider, state);
50	    exChase(camera, controls.target, state, 0, true);
51	    exShowSpeed();
52	    document.body.classList.add('explore');
53	  },
54	  update(dt: number): void {
55	    if (!active()) return;
56	    advance(dt, exInputFromKeys(keys, _inp));
57	  },
58	  /* Cho test: như update nhưng nhận đầu vào trực tiếp */
59	  step(dt: number, inp: GliderInput): void {
60	    if (active()) advance(dt, inp);
61	  },
62	  exit(): void {
63	    const u = new URL(location.href);
64	    u.searchParams.delete('explore'); u.searchParams.delete('chooser');
65	    if (u.href === location.href) location.reload();   // URL chỉ khác phần #ngôn-ngữ: replace chỉ là điều hướng fragment, không tải lại
66	    else location.replace(u.toString());
67	  },
68	};
69	
70	export function setupExplore(ctrl: SwingController): void {
71	  exNightBind(ctrl);
72	  window.addEventListener('keydown', (e) => {
73	    if (!active()) return;
74	    if (e.key === 'Escape') { explore.exit(); return; }   // Esc thoát kể cả khi đang focus ô chọn
75	    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt (Cmd+S...) không lái dù, tránh kẹt phím
76	    const t = e.target as HTMLElement | null;
77	    if (t && /^(SELECT|INPUT|TEXTAREA)$/.test(t.tagName)) return;   // phím trong ô chọn/nhập không lái dù
78	    const k = e.key.toLowerCase(); keys.add(k);
79	    if (k.startsWith('arrow')) e.preventDefault();
80	  });
81	  /* Chọn ngôn ngữ / chất lượng bằng chuột xong thì bỏ focus, nếu không mũi tên và WASD sau đó đổi cài đặt thay vì lái dù. Dùng Tab + bàn phím thì giữ nguyên. */
82	  for (const id of ['langSelect', 'qualitySel']) {
83	    const sel = document.getElementById(id); if (!sel) continue;
84	    let byMouse = false;
85	    sel.addEventListener('pointerdown', () => { byMouse = true; });
86	    sel.addEventListener('keydown', () => { byMouse = false; });
87	    sel.addEventListener('change', () => { if (byMouse && active()) sel.blur(); byMouse = false; });
88	  }
89	  const q = new URLSearchParams(location.search);
90	  exNight.enabled = !q.has('test');   // test bật tường minh qua __app.explore.nightShows
91	  if (q.has('test')) document.body.classList.add('ex-test');   // giữ HUD khi bay để test đo draw call
92	  document.getElementById('btnExExit')?.addEventListener('click', () => explore.exit());
93	  if (q.get('explore') === 'glider') { explore.start(); return; }
94	  if (!q.has('test') || q.has('chooser')) exShowChooser((choice) => { if (choice === 'glider') explore.start(); });   // 'guided': màn chọn tự ẩn, giao diện cũ
95	}
96

1	/* ============================ Tự khám phá: mô hình dù lượn ============================
2	   Một Mesh duy nhất (cánh vòm in cờ đỏ sao vàng + dây + người treo + dải đèn mép cánh), gộp bằng mergeGeometries, vertex color nhân với atlas canvas.
3	   Hệ cục bộ: +X là hướng bay, +Y lên, +Z bên phải. Atlas: phần trên là mặt cánh, dải dưới là màu trơn; emissiveMap cùng bố cục, cường độ đọc shared.uNight.
4	   Mọi thông số nằm ở CONFIG.explore.glider (span, lines = khoảng treo, lineCount, chord, arch, segs). */
5	import * as THREE from 'three';
6	import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
7	import { CONFIG } from '../config';
8	import { shared } from '../core/shared';
9	import type { GliderState } from './flight';
10	
11	const G = CONFIG.explore.glider;
12	const UV_DARK = 0.25, UV_LIT = 0.75;         // u trong dải màu trơn: nửa tối / nửa sáng
13	const TILT = Math.tan(G.tilt);               // độ dốc cánh theo hướng bay (mép sau thấp hơn)
14	const ATLAS_W = 1024, ATLAS_H = 256;         // điểm ảnh atlas
15	const WING_H = 216, BAND_Y = 224;            // mặt cánh chiếm y 0..WING_H; dải màu trơn từ BAND_Y tới đáy; khoảng giữa để đệm
16	const V_SOLID = 1 - (BAND_Y + ATLAS_H) / 2 / ATLAS_H, V_WING0 = 1 - WING_H / ATLAS_H;   // v giữa dải màu trơn; v của mép sau cánh
17	
18	/* Gán uv và màu đỉnh cho hình học không chỉ số */
19	function exPaint(g: THREE.BufferGeometry, rgb: number[], u: number): THREE.BufferGeometry {
20	  const n = g.attributes.position.count, col = new Float32Array(n * 3), uv = new Float32Array(n * 2);
21	  for (let i = 0; i < n; i++) { col.set(rgb, i * 3); uv[i * 2] = u; uv[i * 2 + 1] = V_SOLID; }
22	  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
23	  g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
24	  return g;
25	}
26	
27	/* Dải cánh vòm giữa hai mặt cắt: lệch x0..x1 theo hướng bay, cong xuống ở hai đầu */
28	function exWingStrip(chord0: number, chord1: number, rgb: number[], u: number, lift: number): THREE.BufferGeometry {
29	  const pos: number[] = [];
30	  const half = G.span / 2;
31	  for (let i = 0; i < G.segs; i++) {
32	    const ta = -1 + 2 * i / G.segs, tb = -1 + 2 * (i + 1) / G.segs;
33	    const pa = (t: number, x: number) => [x, -G.arch * half * t * t + lift + x * TILT, t * half];
34	    const a0 = pa(ta, chord0), a1 = pa(ta, chord1), b0 = pa(tb, chord0), b1 = pa(tb, chord1);
35	    pos.push(...a0, ...b0, ...a1, ...a1, ...b0, ...b1);
36	  }
37	  const g = new THREE.BufferGeometry();
38	  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
39	  g.computeVertexNormals();
40	  return exPaint(g, rgb, u);
41	}
42	
43	/* Điểm theo hệ người treo: y tính từ móc treo (−G.lines) */
44	const exP = (x: number, y: number, z: number) => new THREE.Vector3(x, y - G.lines, z);
45	
46	/* Khối bo tròn nối hai điểm (tay, chân, thân) */
47	function exLimb(a: THREE.Vector3, b: THREE.Vector3, r: number, rgb: number[]): THREE.BufferGeometry {
48	  const d = b.clone().sub(a), len = d.length();
49	  const g = new THREE.CapsuleGeometry(r, len, 3, 8).toNonIndexed();
50	  g.applyQuaternion(new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), d.normalize()));
51	  g.translate((a.x + b.x) / 2, (a.y + b.y) / 2, (a.z + b.z) / 2);
52	  return exPaint(g, rgb, UV_DARK);
53	}
54	
55	/* Khối elip tại c, bán trục s */
56	function exBlob(c: THREE.Vector3, s: number[], rgb: number[]): THREE.BufferGeometry {
57	  const g = new THREE.SphereGeometry(1, 12, 8).toNonIndexed();
58	  g.scale(s[0], s[1], s[2]); g.translate(c.x, c.y, c.z);
59	  return exPaint(g, rgb, UV_DARK);
60	}
61	
62	/* Người ngồi trong ghế dù, ngả nhẹ ra sau, chân duỗi về trước, tay cầm dây phanh */
63	function exHuman(parts: THREE.BufferGeometry[]): void {
64	  const JACKET = [0.16, 0.3, 0.55], PANTS = [0.12, 0.13, 0.17], SEAT = [0.05, 0.05, 0.07], BOOT = [0.3, 0.17, 0.08], SKIN = [0.86, 0.66, 0.5], HELMET = [0.92, 0.92, 0.9], VISOR = [0.05, 0.06, 0.1];
65	  parts.push(exBlob(exP(-0.22, -0.68, 0), [0.32, 0.2, 0.3], SEAT));                  // ghế dù
66	  parts.push(exBlob(exP(-0.36, -0.28, 0), [0.14, 0.32, 0.26], SEAT));                // lưng ghế, túi dù dự phòng
67	  parts.push(exLimb(exP(-0.08, -0.62, 0), exP(-0.16, -0.12, 0), 0.19, JACKET));      // thân
68	  for (const z of [-1, 1]) {
69	    parts.push(exLimb(exP(0, 0, z * 0.2), exP(-0.12, -0.3, z * 0.22), 0.025, SEAT));  // đai treo từ móc xuống vai
70	    parts.push(exLimb(exP(-0.04, -0.68, z * 0.13), exP(0.4, -0.7, z * 0.17), 0.085, PANTS));   // đùi
