100	function exDrawWing(x: CanvasRenderingContext2D, glow: boolean): void {
101	  const sx = ATLAS_W / G.span, sy = WING_H / G.chord, cx = ATLAS_W / 2, cy = WING_H / 2;
102	  x.fillStyle = G.flagRed; x.fillRect(0, 0, ATLAS_W, BAND_Y);
103	  x.beginPath();
104	  for (let i = 0; i < 10; i++) {
105	    const r = G.starRadius * (i % 2 ? 0.382 : 1), a = -Math.PI / 2 + i * Math.PI / 5;
106	    x.lineTo(cx + Math.cos(a) * r * sx, cy + Math.sin(a) * r * sy);
107	  }
108	  x.closePath(); x.fillStyle = G.flagStar; x.fill();
109	  x.fillStyle = 'rgba(70,0,0,0.28)';
110	  for (let i = 0; i <= G.cells; i++) x.fillRect(i * ATLAS_W / G.cells - 1, 0, 2, WING_H);
111	  x.fillStyle = 'rgba(70,0,0,0.12)';
112	  for (const k of [0.3, 0.65]) x.fillRect(0, WING_H * k - 1, ATLAS_W, 2);
